export const DataSourceTypeSchema = {
  type: "string",
  description: `Managed exchange data sources available for backtesting.

* \`ticker\` — trades. Can be prepared, executed and swept.
* \`kline\` — aggregated bars (candlesticks). Can be prepared, executed and swept. A run reads
  bars of the \`cadence\` the data was prepared at: you choose the bar width when you prepare,
  and the strategy does not fix it. See \`PrepareRequest.cadence\` for the accepted values.
* \`funding\` — funding rates. Can be **prepared but not executed or swept yet**: a \`funding\`
  request to \`execute\` or \`executeSweep\` is rejected with \`400\` before anything is queued,
  and the message names the sources that can be run.
`,
  enum: ["ticker", "kline", "funding"],
  example: "ticker",
} as const;

export const PrepareRequestSchema = {
  type: "object",
  description: `Two shapes, chosen by the \`exchangeId\` path segment. Against a managed exchange,
\`instrument\` is required and \`datasetId\`/\`datasetVersionId\` are ignored. Against the
reserved \`exchangeId: user\`, send \`datasetId\` instead of \`instrument\` — \`instrument\` is
ignored there, since it comes from the dataset itself.
`,
  required: ["from", "to"],
  properties: {
    instrument: {
      allOf: [
        {
          $ref: "#/components/schemas/Instrument",
        },
      ],
      description: `Required unless \`exchangeId\` is the reserved value \`user\`, in which case send
\`datasetId\` instead.
`,
    },
    datasetId: {
      type: "string",
      description: `Only for \`exchangeId: user\`: the id of a dataset created via \`POST /datasets\`, in place
of \`instrument\`. Ignored against a managed exchange.
`,
      example: "ds_3f9a1c2e7b0d4a5f",
    },
    datasetVersionId: {
      type: "string",
      description: `Only for \`exchangeId: user\`, and optional even then: pins a specific past version of
the dataset instead of its current one. Defaults to the dataset's current version.
`,
      example: "dsv_8e2b4f19c6a03d7e",
    },
    from: {
      type: "string",
      description: `Start date for the preparation process. Supports the following formats:
- ISO-8601 (e.g. 2024-12-14T23:59:59Z)
- ISO DATE (e.g. 2024-12-14)
- BASIC ISO DATE (e.g., 20241214)
`,
      example: "2024-12-13T00:00:00Z",
    },
    to: {
      type: "string",
      description: `End date for the preparation process. Supports the following formats:
- ISO-8601 (e.g. 2024-12-14T23:59:59Z)
- ISO DATE (e.g. 2024-12-14)
- BASIC ISO DATE (e.g., 20241214)
`,
      example: "2024-12-14",
    },
    cadence: {
      type: "string",
      description: `Output bar cadence for the prepared range. Coarser cadences are produced on demand by
resampling the source and stored alongside the native blob in cache. A target finer
than the source, or not an exact multiple of it, returns \`400\`. What's accepted, and
what omitting it means, depends on the source:

* Managed exchange, \`ticker\` or \`funding\` — one of \`1s\`, \`5s\`, \`1m\`, \`3m\`, \`5m\`, \`15m\`,
  \`30m\`, \`1h\`, \`2h\`, \`4h\`, \`8h\`, \`12h\`, \`1d\`, \`1w\`, \`1q\`; any other label returns \`400\`.
  Omitted = \`1s\`, the publisher's native cadence.
* Managed exchange, \`kline\` — the same labels as above, \`1s\` to \`1q\`; a label that is
  not a whole number of seconds returns \`400\`. Omitted = \`1s\`. This is the width of the
  bars a run reads: it is chosen here, once, and the same strategy can be run at
  several cadences by preparing the range at each.
* Dataset (\`exchangeId: user\`) — omitted = the dataset version's own discovered
  \`cadence\` (see \`DatasetVersion.cadence\`), served as-is. Any cadence equal to or
  coarser than it and an exact multiple of it is accepted, including ones outside the
  managed-exchange list (e.g. \`15s\`); an \`rt\` dataset can be resampled to any fixed
  cadence.
`,
    },
  },
  example: {
    instrument: "BTC/USDT",
    from: "2024-12-13T00:00:00Z",
    to: "2024-12-14T00:00:00Z",
    cadence: "1m",
  },
} as const;

export const JobStateSchema = {
  type: "object",
  description: "Information about a single job",
  required: ["contextId", "status", "size", "completed"],
  properties: {
    contextId: {
      type: "string",
      description:
        "Identifier for the job's execution context. Its current shape is a colon-delimited string encoding the data source type, an internal user id, the exchange, the job id, and the instrument — but that structure is not a committed contract and may change without notice. Treat it as an opaque token: store and pass it back, don't parse it.",
      example:
        "jctx:ticker:00000000-0000-0000-0000-000000000000:binance:5ikyamio8b3v9wcnfxztzg:btc/usdt:0vicnz3thzhrqvfczks1pu",
    },
    status: {
      type: "string",
      description: `Current status of the job. Treat \`Completed | Aborted | Failed\` as
terminal; \`New | Started\` mean keep polling. A single-instrument prepare
is always terminal (\`Completed\`) — decide from
\`PrepareJobState.coverageRatio\` (or \`dataFrom\`/\`dataTo\` against an \`rt\` dataset,
which has no ratio), not by polling.
`,
      enum: ["New", "Started", "Completed", "Aborted", "Failed"],
      example: "Completed",
    },
    statusDetail: {
      type: ["string", "null"],
      description: "Detailed status information, if available",
      example: "Job completed with error code 5001",
    },
    size: {
      type: "integer",
      description: "Total size of the data being prepared",
      example: 100,
    },
    completed: {
      type: "integer",
      description: "The amount of data processed so far",
      example: 50,
    },
    startTime: {
      type: ["string", "null"],
      format: "date-time",
      description: "Timestamp for when the preparation started",
      example: "2025-01-04T14:00:00Z",
    },
    endTime: {
      type: ["string", "null"],
      format: "date-time",
      description: "Timestamp for when the preparation finished",
      example: "2025-01-04T14:00:20Z",
    },
    retryable: {
      type: "boolean",
      description: `Present in the \`state\` of an execute job and not in the \`state\` of a prepare. Whether sending
the same request again can succeed once the job has failed: \`true\` for a temporary fault
reading the market data, \`false\` for any other failure, such as a strategy that throws. A job
that has not failed carries \`false\`.
`,
      example: false,
    },
  },
} as const;

export const PrepareJobStateSchema = {
  description: `State of a single-instrument prepare job — the \`JobState\` shape plus a coverage summary.
A single-instrument prepare is always terminal (\`status: Completed\`): the client decides
what to do from \`coverageRatio\` (e.g. execute if it is at or above a chosen threshold)
rather than polling for missing hours that may never arrive — a missing hour for one
instrument usually means low activity, not missing data.

**Two coverage shapes, by exchange vs. dataset.** Against a managed exchange, coverage is
walked hour by hour: \`totalHours\`/\`hoursWithData\`/\`hoursWithoutData\`. Against a
dataset-backed prepare (\`exchangeId: user\`), coverage is reported on the dataset's own
cadence grid instead — hour-walking a daily dataset would report \`1/24\` and read as
broken — via \`cadence\`/\`gaps\`/\`largestGapSteps\`; \`totalHours\`/\`hoursWithData\`/
\`hoursWithoutData\` are absent in that case. \`dataFrom\`/\`dataTo\` are present either way, and
\`coverageRatio\` too, computed accordingly — except against a dataset whose \`cadence\` is \`rt\`:
with no fixed step there is no expected row count to measure against, so \`coverageRatio\`
is absent and \`gaps\`/\`largestGapSteps\` are \`0\`.
`,
  allOf: [
    {
      $ref: "#/components/schemas/JobState",
    },
    {
      type: "object",
      properties: {
        dataFrom: {
          type: ["string", "null"],
          format: "date-time",
          description:
            "Start of the available data range for the prepared instrument.",
          example: "2026-04-14T13:00:00Z",
        },
        dataTo: {
          type: ["string", "null"],
          format: "date-time",
          description:
            "End of the available data range for the prepared instrument.",
          example: "2026-04-14T15:30:05Z",
        },
        coverageRatio: {
          type: "number",
          format: "double",
          minimum: 0,
          maximum: 1,
          description: `Against a managed exchange: \`hoursWithData / totalHours\` in \`[0,1]\` (\`1.0\` when
\`totalHours\` is 0), the fraction of hours in the requested range that have served
data. Against a dataset (\`exchangeId: user\`): \`rows / expectedStepsAtCadence\`
over the dataset version's own range — echoing what ingest computed once, not
recomputed against a narrower prepare request. Absent for an \`rt\` dataset (no
fixed step, so no expected row count).
`,
          example: 0.994,
        },
        totalHours: {
          type: "integer",
          description: `Number of whole hours in the requested prepare range. Managed exchanges only —
absent for a dataset-backed prepare.
`,
          example: 168,
        },
        hoursWithData: {
          type: "integer",
          description: `Number of hours in the range that have data. Managed exchanges only — absent for
a dataset-backed prepare.
`,
          example: 167,
        },
        cadence: {
          type: "string",
          description: `The dataset version's own discovered cadence — a fixed grid (e.g. \`1m\`, \`1h\`) or
\`rt\` (see \`DatasetVersion.cadence\`). Only present for a dataset-backed prepare
(\`exchangeId: user\`).
`,
          example: "1m",
        },
        gaps: {
          type: "integer",
          description: `Number of gaps in the dataset version at its own cadence, as discovered at ingest
time. \`0\` for \`rt\`. Only present for a dataset-backed prepare.
`,
          example: 0,
        },
        largestGapSteps: {
          type: "integer",
          description: `The largest gap in the dataset version, in units of its own cadence step. \`0\` for
\`rt\`. Only present for a dataset-backed prepare.
`,
          example: 0,
        },
        hoursWithoutData: {
          type: "array",
          description: `One entry per hour in the range that has no data, with a rationale. Managed
exchanges only — absent for a dataset-backed prepare.
`,
          items: {
            type: "object",
            properties: {
              hour: {
                type: "string",
                format: "date-time",
                description: "The hour (UTC, hour-aligned) that has no data.",
                example: "2026-04-14T02:00:00Z",
              },
              expected: {
                type: "integer",
                description: `Expected row count for the hour (currently always 0; reserved for
future use). The rationale never depends on it.
`,
                example: 0,
              },
              rationale: {
                type: "string",
                description: `Why the hour has no data. \`pending_conversion\`: data for this hour is
still being produced — a re-poll may fill it. \`low_activity\`: the
instrument did not trade that hour. \`unknown\`: no data to classify by.
`,
                enum: ["pending_conversion", "low_activity", "unknown"],
                example: "low_activity",
              },
            },
          },
        },
      },
    },
  ],
} as const;

