export const EquityCurveOptionsSchema = {
  type: "object",
  description:
    "Requested equity-curve transform, applied server-side in a fixed pipeline order: `resample` (point count) then `differential` (encoding) then `outMode` (JSON shape) — each stage assumes the previous one already ran. A server-side size guard can still force a smaller/deflated shape above its thresholds regardless of what is requested here — see `EquityCurveMeta` for what actually happened.",
  properties: {
    resample: {
      type: "integer",
      minimum: 2,
      description:
        "Downsample to at most this many points (extrema-preserving — the global max/min and the exact first/last point are always kept). Omit for no downsampling.",
    },
    differential: {
      type: "boolean",
      default: false,
      description:
        "Delta-encode both fields from the second (post-resample) point onward.",
    },
    outMode: {
      allOf: [
        {
          $ref: "#/components/schemas/EquityCurveOutMode",
        },
      ],
      default: "ARRAY",
      description: "Requested JSON shape.",
    },
  },
} as const;

export const EquityCurveRequestSchema = {
  allOf: [
    {
      $ref: "#/components/schemas/EquityCurveOptions",
    },
    {
      type: "object",
      properties: {
        mode: {
          type: "string",
          enum: ["auto", "topN", "topPct", "none"],
          default: "auto",
          description:
            "Which trials keep their per-point equity curve. `auto` retains curves only while the accumulated size stays within server limits; `topN`/`topPct` retain curves for the best-ranked trials explicitly; `none` retains no curves.",
        },
        n: {
          type: "integer",
          minimum: 1,
          description: "Trial count to retain when mode is topN.",
        },
        maxPct: {
          type: "number",
          format: "double",
          exclusiveMinimum: 0,
          maximum: 100,
          description:
            "Top percentage of trials to retain when mode is topPct.",
        },
      },
    },
  ],
  description:
    "Selection (`mode`/`n`/`maxPct`) plus the transform preference (`resample`/`differential`/`outMode`) applied by `GET .../equityCurve` whenever ITS OWN query params are absent, for a curve this sweep retained. The transform half never affects retention or `sweepId` — a caller can always override it per-request at read time regardless of what was submitted here.",
} as const;

export const WalkForwardRequestSchema = {
  type: "object",
  description:
    "Opt in to walk-forward validation. Present, the sweep runs as F sequential folds and the result gains a `walkForward` section; absent, nothing about the sweep changes. Two requests that differ only in this block are two different sweeps and do not deduplicate against each other.",
  required: ["folds"],
  properties: {
    folds: {
      type: "integer",
      minimum: 2,
      description: `How many sequential optimize-then-score windows to run. Two is the minimum for a reason, and it is structural rather than a tuning choice: parameter drift is measured between consecutive fold winners, and a single fold — one train/test split with no sequence — has no consecutive pair to compare, so it would report the strongest possible stability having measured nothing.
The upper bound is a server setting (12 by default) and is deliberately not pinned here, since a spec that hardcodes a tunable limit lies the day it is raised. Exceeding it, or exceeding the sweep budget once multiplied by the grid size, is a 400.`,
    },
    inSamplePct: {
      type: "integer",
      minimum: 10,
      maximum: 90,
      default: 66,
      description:
        "Share of the session each fold spends optimizing; the remainder is where its winner is scored. Lower values leave more data to be scored on and, on short sessions, are also what lets the requested fold count tile the data at all.",
    },
  },
} as const;

