export const SweepProgressSchema = {
  type: "object",
  description:
    "How far along a sweep is, and — when the sweep is still running — enough to tell a healthy one from a stuck one. The counts partition the shards (or, for a walk-forward sweep, the folds): every unit is either finished, failed, waiting to be retried, or not yet started.",
  required: [
    "done",
    "total",
    "aborted",
    "shardCount",
    "pendingShards",
    "failedShards",
    "retrying",
    "notStarted",
  ],
  properties: {
    done: {
      type: "integer",
      format: "int64",
    },
    total: {
      type: "integer",
    },
    aborted: {
      type: "integer",
      format: "int64",
      description:
        "Individual runs that executed and aborted. A row-level count: a shard that fails before producing any rows leaves this at 0, which is why `failedShards` exists alongside it.",
    },
    shardCount: {
      type: "integer",
    },
    pendingShards: {
      type: "integer",
      description:
        "Shards (or folds) that have not finished yet. On a cancelled sweep, `0` is what says every run that was in flight has finished and the leaderboard is complete: `CANCELLED` is reported before that.",
    },
    failedShards: {
      type: "integer",
      format: "int64",
      description:
        "Shards (or folds) that failed and will not be retried. Distinct from `aborted`: this counts whole units that never reported, not runs that ran badly.",
    },
    retrying: {
      type: "integer",
      description:
        "Units whose last attempt failed on something transient — an I/O error, a worker that died mid-read — and which are queued to be attempted again. Not counted as failures, because they have not failed yet; a sweep with a non-zero value here is still expected to complete.",
    },
    notStarted: {
      type: "integer",
      description:
        "Units that have not reported anything yet. Covers both work still queued behind other work and work claimed by a worker that stopped before it began, which is why a sweep with a persistent value here and a rising `stalledSeconds` is worth looking at.",
    },
    stalledSeconds: {
      type: "integer",
      format: "int64",
      description:
        "Seconds since anything last advanced. Omitted on a finished sweep, where it would only measure how long ago it finished, and on sweeps submitted before this field existed.",
    },
    etaSeconds: {
      type: "integer",
      format: "int64",
      description:
        'Rough seconds remaining, extrapolated from the rate observed so far and assuming nothing else competes for workers. Runs conservative in practice — it has measured 2–5× long when a sweep spent part of its life waiting to be retried, since that wait dilutes the observed rate. **Omitted, never zero, when it cannot be computed**: a sweep with nothing finished yet has no rate to extrapolate from, and a zero would read as "about to finish". Excludes queue wait entirely; `retrying` and `stalledSeconds` are where that shows up.',
    },
  },
} as const;

export const SweepRunRowSchema = {
  type: "object",
  required: [
    "runIx",
    "params",
    "sharpe",
    "sortino",
    "pnl",
    "pnlPct",
    "cagr",
    "maxDdPct",
    "trades",
    "winRate",
    "belowTradeFloor",
    "aborted",
    "runtimeMs",
  ],
  properties: {
    runIx: {
      type: "integer",
      minimum: 0,
      description:
        "Deterministic zero-based expansion index, stable across shards and ranking.",
    },
    rank: {
      type: "integer",
      minimum: 1,
      description: "Present only in the `ranked` view.",
    },
    plateauScore: {
      type: "number",
      format: "double",
      description:
        "The objective of the worst run in this point's immediate neighbourhood — how well the region around it holds up, not how well it scored itself. Present only in the `ranked` view when plateau ranking applied. Always read together with `neighbourCount`.",
    },
    neighbourCount: {
      type: "integer",
      minimum: 0,
      description:
        "How many neighbouring parameter points backed the `plateauScore`. Zero means the point had no neighbours in the grid, so its score is unevidenced rather than confirmed — the value alone cannot be distinguished from a genuinely robust one.",
    },
    deflatedSharpe: {
      type: "number",
      format: "double",
      minimum: 0,
      maximum: 1,
      description:
        "Probability that this run's Sharpe reflects real edge rather than the best draw from however many parameter vectors were tried. Above ~0.95 the result survives the multiple-testing correction; near 0.5 or below it is indistinguishable from the best of a pile of coin flips. Absent on aborted runs, on sweeps with too few trials to establish any dispersion to deflate against, on runs with fewer than 3 period returns, and on a degenerate (near-constant) return series — all cases where the underlying statistic isn't meaningfully computable, rather than genuinely zero. A present value is the computed probability, however small.",
    },
    params: {
      type: "object",
      additionalProperties: true,
    },
    sharpe: {
      type: "number",
      format: "double",
    },
    sortino: {
      type: "number",
      format: "double",
    },
    pnl: {
      type: "number",
      format: "double",
      description: "Absolute net PnL in the output currency.",
    },
    pnlPct: {
      type: "number",
      format: "double",
      description:
        "Same units as `pnlTotalPercent` on the single-run result — percent (0-100 scale).",
    },
    cagr: {
      type: "number",
      format: "double",
      description:
        "Same units as `cagr` on the single-run result — a ratio, not a percent.",
    },
    maxDdPct: {
      type: "number",
      format: "double",
      description:
        "Same units as `maxDrawdownPercent` on the single-run result — percent (0-100 scale).",
    },
    trades: {
      type: "integer",
      format: "int64",
    },
    winRate: {
      type: "number",
      format: "double",
      description:
        "Same units as `winRate` on the single-run result — a fraction, 0.0-1.0 (a rate, not a percent).",
    },
    belowTradeFloor: {
      type: "boolean",
    },
    aborted: {
      type: "boolean",
    },
    runtimeMs: {
      type: "integer",
      format: "int64",
    },
    equityCurve: {
      allOf: [
        {
          $ref: "#/components/schemas/EquityCurveResult",
        },
      ],
      description: `Present whenever this trial actually has a curve — which is any completed run of a sweep that requested curves at all (\`equityCurve.mode\` \`topN\`/\`topPct\`), not only the ranked winners. Absent, not null, when there is genuinely nothing: the run aborted, it made no trades, or the sweep never retained curves (\`mode\` \`auto\`/\`none\`).
Selection decides how the curve travels, not whether it exists. A row may carry \`url\` alone, or \`url\` together with the points inline.
**Read \`points\`/\`equities\` to tell whether the curve is inline — never the presence of this object, and never the absence of \`url\`.** Both mislead, and in opposite directions: this object is present on rows that carry only a pointer, and \`url\` stays present alongside an inline curve so a caller can still re-request a different transform. An inline curve is emitted on the materialisation view (\`?order=natural\`), where each row is read once; the ranked view keeps the pointer, being polled.
When only a pointer is present, \`GET\` the \`url\` for the curve. Its own \`meta\` there is the real, possibly size-guarded outcome. This outer \`meta\` may be a declaration rather than a measurement — for a row whose curve was not promoted, the point count is derived from the trade count (one equity point per closed trade) instead of being read from the store, to keep a polled response from doing per-row work.`,
    },
  },
} as const;

