export const LiveRunSchema = {
  type: "object",
  required: [
    "strategyId",
    "runId",
    "visibility",
    "stage",
    "state",
    "desired",
    "sources",
    "params",
    "paramsVersion",
    "relay",
    "startedAtMs",
  ],
  description:
    "A live run's full state, as returned by stopping it through its strategy, and the base of the representations returned by starting and by reading it. `warmFrom` is declared by those two (`LiveRunWithStream` and `LiveRunDetail`) and not here, because the response to stopping a run does not carry it.",
  properties: {
    strategyId: {
      $ref: "#/components/schemas/strategyId",
    },
    runId: {
      type: "string",
      description:
        "This run's own id — its canonical identity for `PATCH`/`PUT .../params` and for `GET /live/public`.",
    },
    name: {
      type: "string",
    },
    description: {
      type: "string",
    },
    visibility: {
      type: "string",
      enum: ["private", "public"],
    },
    stage: {
      type: "string",
      enum: ["SANDBOX", "LIVE"],
      description:
        "A new run starts `SANDBOX`, a trial of `sandboxMinutes` minutes at least, and never more than 24 hours, in which it is compared against a second execution and checked for resource use and stability. A run that passes moves to `LIVE` automatically when the trial is over. A run of a strategy that an earlier run of yours already took through the trial starts `LIVE`, unless you started it with `sandbox: true`.",
    },
    state: {
      type: "string",
      description:
        "The run's health right now: `STARTING` (no runner has reported on it yet), `RUNNING`, `LAGGING` (behind the market data, usually while catching up; clears by itself), `HUNG` (stuck inside one strategy call for longer than allowed; clears when it returns), `DEGRADED` (its independent executions produced different signals), `FAILED` (refused, could not start or failed while running; `reason` says why) or `STOPPED`. `LAGGING`, `HUNG` and `DEGRADED` come and go on a running run. The set may grow: read an unknown value as a running run with something to look at. See the Live execution guide.",
    },
    desired: {
      type: "string",
      enum: ["RUNNING", "STOPPED"],
      description:
        "What you last asked for. `state` can lag this briefly after `DELETE`.",
    },
    reason: {
      type: "string",
      description: `Why the run stopped or failed, when there is something to say; absent otherwise. It is never a
stack trace or an internal message. Either \`resource: ...\` (the platform stopped the run for
exceeding its resource allowance; the text says which limit) or one of a fixed set of sentences for
a \`FAILED\` run: the strategy cannot consume the source type the run was started with, the run's
definition was refused, the pool address of a \`dex\` run is not a pool of its protocol on its chain,
the platform has no room to follow the pool of a \`dex\` run, the run could not start after several
attempts, the strategy failed while processing data, the run lost its data feed, or the generic
\`The run failed.\`. The set may grow:
read an unrecognised sentence as a failure and do not parse it. A \`FAILED\` run usually stays
\`desired: RUNNING\` until you stop it, and counts as active (\`409\` on a new start, and toward your
live-run limit) until then; one that cannot run, and will not by waiting, because its strategy cannot
consume its source type or because the pool of a \`dex\` run is not a pool or has no room to be followed,
is stopped by the platform itself (\`desired: STOPPED\`), so it holds no place.
`,
    },
    sources: {
      type: "array",
      items: {
        $ref: "#/components/schemas/LiveSource",
      },
    },
    params: {
      type: "object",
      additionalProperties: true,
    },
    paramsVersion: {
      type: "integer",
      description:
        "Increments on every accepted `PUT .../params` call, including one that resends the current values.",
    },
    relay: {
      type: "boolean",
      description: `Whether this run's signals are relayed over the WebSocket channel described in the "Live execution" guide. It is the value requested at start, in either stage.`,
    },
    startedAtMs: {
      type: "integer",
      format: "int64",
      description: "Epoch milliseconds.",
    },
    gate: {
      type: "object",
      additionalProperties: true,
      description:
        "The sandbox trial's promotion verdict. Absent for the whole trial and present once it ends, so an absent `gate` means the trial has not finished. A run that started in `LIVE` without a trial has it from the start: the verdict of the earlier run it relies on, with `inheritedFrom` naming that run. `passed` is the verdict; the rest is diagnostic detail whose shape is not yet stabilized as public API: treat it as opaque.",
    },
    paper: {
      allOf: [
        {
          $ref: "#/components/schemas/LivePaperConfig",
        },
      ],
      description:
        "The run's paper trading configuration as accepted at start, normalised. Absent when the run has no paper trading.",
    },
    stats: {
      allOf: [
        {
          $ref: "#/components/schemas/LiveRunStats",
        },
      ],
      description: `The run's latest counters. Returned by the two reads, \`GET /strategy/{strategyId}/live\` and
\`GET /live/{runId}\`; never by starting or stopping a run. Absent until the first snapshot exists
(a run that has just started), and absent is not zero.
`,
    },
  },
} as const;

export const LiveRunStatsSchema = {
  type: "object",
  required: ["processed", "opsPerSecond", "instrumentsSeen", "asOfMs", "stale"],
  description: `What a run has been doing, as of its last snapshot. The platform refreshes it about once a minute
while the run is being executed, so \`opsPerSecond\` is an average over that interval, not an
instantaneous rate.
`,
  properties: {
    processed: {
      type: "integer",
      format: "int64",
      description:
        "Updates of instruments the run has accepted since it started executing. It can start again from zero if the run is restarted.",
    },
    opsPerSecond: {
      type: "number",
      description:
        "Updates accepted per second over the last refresh interval. `0` when none arrived.",
    },
    instrumentsSeen: {
      type: "integer",
      description:
        "How many distinct instruments the run has received an update for.",
    },
    asOfMs: {
      type: "integer",
      format: "int64",
      description: "Epoch milliseconds when these counters were last written.",
    },
    progressedAtMs: {
      type: "integer",
      format: "int64",
      description: `Epoch milliseconds of the last snapshot in which \`processed\` had grown. Absent until the run has
processed anything. A run fed by a source that updates rarely (a funding rate, for example) can
stay flat for hours: that is how such a run behaves, not a fault.
`,
    },
    stale: {
      type: "boolean",
      description: `\`true\` when the run is meant to be running (\`desired\` is \`RUNNING\`) and its counters have not
been refreshed for several refresh intervals: the platform has stopped updating them, which is
worth checking against \`state\`. \`false\` otherwise. A run whose \`processed\` is flat is not stale;
\`progressedAtMs\` is how to tell it apart.
`,
    },
  },
} as const;

