export const LivePaperEquityCurveSchema = {
  description:
    "One paper account's equity curve: the API's one equity curve (`EquityCurveResult`, `{points|timestamps+equities, meta}`) with the account's `currency` and the `gaps` alongside.",
  allOf: [
    {
      $ref: "#/components/schemas/EquityCurveResult",
    },
    {
      type: "object",
      required: ["gaps", "measure"],
      properties: {
        currency: {
          type: "string",
          description:
            "The account's quote currency. Absent only when the run has no account yet, which gives an empty curve.",
        },
        instrument: {
          type: "string",
          example: "BTC/USDT",
          description:
            "Present when the curve is one instrument's (`measure` is `realisedPnl` or `totalPnl`) and, in a run started with `accounts: instrument`, when it is the curve of the account that instrument is (`measure` is `equity`).",
        },
        measure: {
          type: "string",
          enum: ["equity", "realisedPnl", "totalPnl"],
          description:
            "What the values of the curve are: the account's `equity`, an instrument's cumulative `realisedPnl` from 0, or its `totalPnl` (the realised PnL plus the unrealised value of its open position). The shape names its values `equity` in every case.",
        },
        gaps: {
          type: "array",
          description:
            "Market times (epoch ms, oldest first) at which open positions were lost because the run was restarted with them open. A gap is not a point of the curve and is not counted in `meta`.",
          items: {
            type: "integer",
            format: "int64",
          },
        },
        _links: {
          type: "object",
          description:
            "Present on a page of the raw curve while there is a next one.",
          properties: {
            next: {
              type: "object",
              properties: {
                href: {
                  type: "string",
                  description:
                    "The next page; follow it as given, the cursor is opaque.",
                },
              },
            },
          },
        },
      },
    },
  ],
} as const;

export const LiveSignalSchema = {
  type: "object",
  required: [
    "v",
    "signalId",
    "runId",
    "stage",
    "type",
    "eventTsMs",
    "emittedAtMs",
    "instrument",
    "digest",
  ],
  description:
    "One signal, in the same shape the real-time signal channel delivers.",
  properties: {
    v: {
      type: "integer",
      description: "Envelope schema version.",
    },
    signalId: {
      type: "string",
      description:
        "Stable id for this exact signal — dedupe on it across reconnects or overlapping reads.",
    },
    runId: {
      type: "string",
    },
    stage: {
      type: "string",
      enum: ["sandbox", "live"],
      description: "The stage the run was in when this signal was produced.",
    },
    paramsVersion: {
      type: "integer",
      description: "The parameter set in force when this signal was produced.",
    },
    type: {
      type: "string",
      enum: ["hint", "info", "marker", "command", "paper"],
      description: `\`paper\` items appear only for a run whose \`paper.output\` is \`mix\`; they are not relayed over the WebSocket channel.`,
    },
    kind: {
      type: ["string", "null"],
      description: `\`BUY\`/\`SELL\` for a \`hint\`, the command name for a \`command\`; for \`paper\`, what the item is: \`fill\`, \`trade\`, \`equity\`, \`mark\`, \`kpi\` or \`gap\`. Absent otherwise.`,
    },
    eventTsMs: {
      type: "integer",
      format: "int64",
      description: "Market time the signal was produced.",
    },
    emittedAtMs: {
      type: "integer",
      format: "int64",
      description: "Time it was published — always at or after `eventTsMs`.",
    },
    instrument: {
      anyOf: [
        {
          $ref: "#/components/schemas/LiveSignalInstrument",
        },
        {
          type: "null",
        },
      ],
      description:
        "The instrument the signal is about. `null` only for a `paper` item about a whole account (`equity`, `mark`, `kpi`), whose `data.currency` names the account.",
    },
    order: {
      $ref: "#/components/schemas/LiveSignalOrder",
    },
    data: {
      type: "object",
      additionalProperties: true,
      description:
        "The signal's own free-form payload, what the strategy put there with `signal.set(...)`. Whoever may read the run may read it, so on a `public` run it is public. A signal whose `data` is over 8 KiB (8,192 bytes of its JSON) is not pushed on the WebSocket channel, and `GET /live/{runId}/signals` returns it whole.",
    },
    regenerated: {
      type: "boolean",
      description: `\`true\` only for a signal republished to fill a gap in the record.`,
    },
    digest: {
      type: "string",
      description:
        "Content hash, for checking that two independent deliveries of the same signal agree.",
    },
  },
} as const;

